package io.knowledgebrain.content;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import tools.jackson.databind.json.JsonMapper;
import tools.jackson.databind.JsonNode;
import com.google.protobuf.ByteString;

/** Canonical bounded recovery feed, reading only Content-owned current/audit tables. */
final class ContentRecordSnapshots {
 static BrainSnapshotController.Page page(JdbcTemplate jdbc,JsonMapper json,String kind,UUID after,UUID through,int limit){
  boolean links=kind.endsWith("_CONCEPTS");String type=links?kind.substring(0,kind.length()-9):kind;
  // Enum validation makes every SQL identifier a compile-time owned table choice.
  String table=RecordConceptStore.Kind.valueOf(type).table;
  String source=links?"record_concepts h":""+table+" h",entity=links?"record_id":table+"_id",where=links?"h.record_type='"+type+"'":"true";
  if(through==null){var ids=jdbc.query("SELECT "+entity+" FROM "+source+" WHERE "+where+" ORDER BY "+entity+" DESC LIMIT 1",(rs,n)->rs.getObject(1,UUID.class));if(ids.isEmpty())return new BrainSnapshotController.Page(null,null,List.of());through=ids.getFirst();}
  String sql=links?"SELECT h.record_id,h.space_id,r.revision_id,h.version,r.actor_id,r.occurred_at,r.snapshot::text,r.record_version FROM record_concepts h JOIN record_concept_revision r ON r.association_id=h.association_id AND r.version=h.version":"SELECT h."+entity+",h.space_id,r.revision_id,h.version,r.actor_id,r.occurred_at,r.snapshot::text,0 FROM "+table+" h JOIN "+table+"_revision r ON r."+entity+"=h."+entity+" AND r.version=h.version";
  sql+=" WHERE "+where+" AND h."+entity+"<=?"+(after==null?"":" AND h."+entity+">?")+" ORDER BY h."+entity+" LIMIT ?";
  var items=jdbc.query(sql,(rs,n)->{UUID id=rs.getObject(1,UUID.class),space=rs.getObject(2,UUID.class),revision=rs.getObject(3,UUID.class);long version=rs.getLong(4),time=rs.getTimestamp(6).toInstant().toEpochMilli();String actor=rs.getString(5);var value=json.readTree(rs.getString(7));byte[] wire;
   if(links){var p=io.knowledgebrain.contracts.content.recordconcepts.v1.RecordConceptsChangedPayloadV1.newBuilder().setAssociationId(value.path("associationId").asString()).setRecordType(type).setRecordId(id.toString()).setVersion(version).setRecordVersion(rs.getLong(8)).setRecordState("ACTIVE").setRevisionId(revision.toString());for(var v:value.path("items"))p.addLinks(io.knowledgebrain.contracts.content.recordconcepts.v1.RecordConceptLinkV1.newBuilder().setLinkId(v.path("linkId").asString()).setConceptId(v.path("conceptId").asString()));wire=io.knowledgebrain.contracts.content.recordconcepts.v1.RecordConceptEventEnvelopeV1.newBuilder().setEventId(revision.toString()).setProducer("content-service").setAggregateType("RecordConceptLinks").setAggregateId(value.path("associationId").asString()).setSpaceId(space.toString()).setActorId(actor).setOccurredAtEpochMillis(time).setTraceId("e".repeat(32)).setEventVersion(1).setEventType("RecordConceptsChanged").setPayload(p.build().toByteString()).build().toByteArray();}
   else wire=source(type,id,space,revision,version,actor,time,value);
   return new BrainSnapshotController.Item(id,space,version,Base64.getEncoder().encodeToString(wire));
  },after==null?new Object[]{through,limit+1}:new Object[]{through,after,limit+1});var rows=List.copyOf(items.subList(0,Math.min(limit,items.size())));return new BrainSnapshotController.Page(through,items.size()>limit?rows.getLast().entityId():null,rows);
 }
 private static byte[] source(String kind,UUID id,UUID space,UUID revision,long version,String actor,long time,JsonNode v){time=java.time.Instant.parse(v.path("updatedAt").asString()).toEpochMilli();switch(kind){
 case "BOOKMARK":{var p=io.knowledgebrain.contracts.content.bookmark.v1.BookmarkChangedPayloadV1.newBuilder().setBookmarkId(id.toString()).setRevisionId(revision.toString()).setVersion(version).setVisibility("PRIVATE").setState(v.path("state").asString()).setTitle(v.path("title").asString()).setUrl(v.path("url").asString()).setMemo(v.path("memo").asString()).setCreatedAt(v.path("createdAt").asString()).setUpdatedAt(v.path("updatedAt").asString()).build();return io.knowledgebrain.contracts.content.bookmark.v1.BookmarkEventEnvelopeV1.newBuilder().setEventId(revision.toString()).setProducer("content-service").setAggregateType("Bookmark").setAggregateId(id.toString()).setSpaceId(space.toString()).setActorId(actor).setOccurredAtEpochMillis(time).setTraceId("e".repeat(32)).setEventVersion(1).setEventType(v.path("state").asString().equals("RETIRED")?"BookmarkRetired":version==1?"BookmarkCreated":"BookmarkUpdated").setPayload(p.toByteString()).build().toByteArray();}
 case "QUESTION":{var p=io.knowledgebrain.contracts.content.question.v1.QuestionChangedPayloadV1.newBuilder().setQuestionId(id.toString()).setRevisionId(revision.toString()).setVersion(version).setVisibility("PRIVATE").setState(v.path("state").asString()).setTitle(v.path("title").asString()).setContext(v.path("context").asString()).setAnswer(v.path("answer").asString()).setStatus(v.path("status").asString()).setCreatedAt(v.path("createdAt").asString()).setUpdatedAt(v.path("updatedAt").asString()).build();return io.knowledgebrain.contracts.content.question.v1.QuestionEventEnvelopeV1.newBuilder().setEventId(revision.toString()).setProducer("content-service").setAggregateType("Question").setAggregateId(id.toString()).setSpaceId(space.toString()).setActorId(actor).setOccurredAtEpochMillis(time).setTraceId("e".repeat(32)).setEventVersion(1).setEventType(v.path("state").asString().equals("RETIRED")?"QuestionRetired":version==1?"QuestionCreated":"QuestionUpdated").setPayload(p.toByteString()).build().toByteArray();}
 case "DECISION":{var p=io.knowledgebrain.contracts.content.decision.v1.DecisionChangedPayloadV1.newBuilder().setDecisionId(id.toString()).setRevisionId(revision.toString()).setVersion(version).setVisibility("PRIVATE").setState(v.path("state").asString()).setTitle(v.path("title").asString()).setContext(v.path("context").asString()).setOutcome(v.path("outcome").asString()).setRationale(v.path("rationale").asString()).setAlternatives(v.path("alternatives").asString()).setStatus(v.path("status").asString()).setCreatedAt(v.path("createdAt").asString()).setUpdatedAt(v.path("updatedAt").asString()).build();return io.knowledgebrain.contracts.content.decision.v1.DecisionEventEnvelopeV1.newBuilder().setEventId(revision.toString()).setProducer("content-service").setAggregateType("Decision").setAggregateId(id.toString()).setSpaceId(space.toString()).setActorId(actor).setOccurredAtEpochMillis(time).setTraceId("e".repeat(32)).setEventVersion(1).setEventType(v.path("state").asString().equals("RETIRED")?"DecisionRetired":version==1?"DecisionCreated":"DecisionUpdated").setPayload(p.toByteString()).build().toByteArray();}
 default:throw new IllegalArgumentException("Unknown record snapshot");}}
}
